WITH flattened_attrs AS (SELECT id, service, payload_json, context, COALESCE(context['region'], 'unknown') AS region_or_default, context['trace'] AS trace, CAST((status_code & 2) != 0 AS INT) AS has_fault FROM app_logs) SELECT service, COUNT(DISTINCT region_or_default) AS distinct_region_or_defaults, PERCENTILE_APPROX(has_fault, 0.5) AS has_fault_p50 FROM flattened_attrs GROUP BY service HAVING distinct_region_or_defaults > 1 ORDER BY distinct_region_or_defaults DESC NULLS FIRST
